import { parsePackageJsonDependencies } from '@mintlify/common';
import { readFile } from 'fs/promises';
import { join } from 'path';
export const readPackageNames = async (contentDirectoryPath) => {
    try {
        const content = await readFile(join(contentDirectoryPath, 'package.json'), 'utf8');
        return parsePackageJsonDependencies(content).packageNames;
    }
    catch {
        return new Set();
    }
};
